-- Phase 2 extraction seed for the 04-03-2024 consolidated source only.
-- Source facts are kept separate from normalized candidate descriptions.
SELECT document_id, provision_id,
       CASE
         WHEN provision_type = 'ARTICLE' AND article = '1' THEN 'SCOPE'
         WHEN provision_type = 'ARTICLE' AND article = '2' THEN 'DEFINITION'
         WHEN provision_type = 'ARTICLE' AND article BETWEEN '3' AND '8' THEN 'OBLIGATION'
         WHEN provision_type = 'ARTICLE' AND article = '9' THEN 'PROCEDURAL'
         WHEN provision_type = 'ARTICLE' AND article = '10' THEN 'OBLIGATION'
         WHEN provision_type = 'ARTICLE' AND article = '11' THEN 'DEADLINE'
         WHEN provision_type = 'DATA_ELEMENT' THEN 'SCOPE'
         WHEN provision_type IN ('ANNEX','ANNEX_SECTION','ANNEX_LEVEL','ANNEX_GROUP') THEN 'SCOPE'
         ELSE 'OTHER'
       END,
       CASE WHEN provision_type = 'ARTICLE'
            THEN 'Classification at article granularity; mixed paragraphs are classified at candidate level.'
            ELSE 'Annex data category defines the scope of related duties; it does not itself assert an independent duty.' END
FROM source.provisions
WHERE document_id = 'EU-REG-2017-1926'
ON CONFLICT (source_document_id, source_provision_id) DO UPDATE SET
    legal_classification=excluded.legal_classification,
    classification_notes=excluded.classification_notes;

ON CONFLICT (source_fact_id) DO UPDATE SET
    legal_reference=excluded.legal_reference,
    source_fact_text=excluded.source_fact_text,
    source_version_date=excluded.source_version_date,
    source_uri=excluded.source_uri,
    notes=excluded.notes;

ON CONFLICT (candidate_id) DO NOTHING;

ON CONFLICT (candidate_id,source_provision_id) DO NOTHING;

SELECT c.requirement_id,'EU',c.source_document_id,c.source_provision_id,c.requirement_class,c.requirement_type,c.description,c.responsible_party,c.beneficiary_party,c.is_mandatory,c.is_conditional,c.accessibility_requirement,c.deadline_date,NULL,FALSE,'Materialized from an approved Phase 2 candidate; see compliance.requirement_candidates and compliance.source_facts.'
FROM compliance.requirement_candidates c
WHERE c.source_document_id='EU-REG-2017-1926'
  AND c.review_status='APPROVED'
  AND c.requirement_id IS NOT NULL
ON CONFLICT (requirement_id) DO UPDATE SET
    jurisdiction=excluded.jurisdiction,
    source_document_id=excluded.source_document_id,
    source_provision_id=excluded.source_provision_id,
    requirement_class=excluded.requirement_class,
    requirement_type=excluded.requirement_type,
    description=excluded.description,
    responsible_party=excluded.responsible_party,
    beneficiary_party=excluded.beneficiary_party,
    is_mandatory=excluded.is_mandatory,
    is_conditional=excluded.is_conditional,
    accessibility_requirement=excluded.accessibility_requirement,
    deadline_date=excluded.deadline_date,
    is_auditable=excluded.is_auditable,
    notes=excluded.notes;

SELECT c.requirement_id || '-DL-001',c.requirement_id,'EU',c.deadline_date,'REPORTING',
       'Remitir a la Comisión el informe indicado en el artículo 10, apartado 1.',
       'Medidas para establecer el punto de acceso nacional y modalidades de funcionamiento.',
       c.source_document_id,c.source_provision_id,'Fecha expresa en el texto consolidado 2024-03-04.'
FROM compliance.requirement_candidates c
WHERE c.review_status='APPROVED' AND c.deadline_date IS NOT NULL
  AND c.source_document_id='EU-REG-2017-1926'
ON CONFLICT (deadline_id) DO UPDATE SET
    requirement_id=excluded.requirement_id,
    jurisdiction=excluded.jurisdiction,
    deadline_date=excluded.deadline_date,
    deadline_type=excluded.deadline_type,
    description=excluded.description,
    scope_description=excluded.scope_description,
    source_document_id=excluded.source_document_id,
    source_provision_id=excluded.source_provision_id,
    notes=excluded.notes;
