INSERT INTO compliance.provision_classifications
    (source_document_id, source_provision_id, legal_classification, classification_notes)
INSERT INTO compliance.source_facts VALUES
('EU-2017-1926-SF-A03-P01-ESTABLISH','EU-REG-2017-1926','EU-2017-1926-ART03','Artículo 3, apartado 1','Cada Estado miembro deberá crear un punto de acceso nacional.','2024-03-04','https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304','Extracto literal del texto consolidado; no modifica source.provisions.'),
('EU-2017-1926-SF-A03-P01-SINGLE','EU-REG-2017-1926','EU-2017-1926-ART03','Artículo 3, apartado 1','El punto de acceso nacional constituirá un punto de acceso único para los usuarios de datos a los datos estáticos, históricos, observados y dinámicos sobre desplazamientos y tráfico de los diferentes modos de transporte, incluidas las actualizaciones de datos, tal como se indica en el anexo, suministrados por los titulares de datos en el territorio de un Estado miembro determinado.','2024-03-04','https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304','Extracto literal del texto consolidado; contiene el alcance del punto único.'),
('EU-2017-1926-SF-A03-P03','EU-REG-2017-1926','EU-2017-1926-ART03','Artículo 3, apartado 3','Los puntos de acceso nacionales prestarán servicios de localización a los usuarios de datos.','2024-03-04','https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304',''),
('EU-2017-1926-SF-A03-P04','EU-REG-2017-1926','EU-2017-1926-ART03','Artículo 3, apartado 4','Los Estados miembros, en cooperación con las partes interesadas pertinentes de los STI, alcanzarán un acuerdo sobre los requisitos en materia de metadatos. Los titulares de datos se asegurarán de que facilitan los metadatos sobre la base de dichos requisitos.','2024-03-04','https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304','La norma no detalla aquí los requisitos acordados.'),
('EU-2017-1926-SF-A04-P01','EU-REG-2017-1926','EU-2017-1926-ART04','Artículo 4, apartado 1','Los titulares de datos facilitarán, a través del punto de acceso nacional establecido de conformidad con el artículo 3, acceso a los datos estáticos, históricos y observados sobre desplazamientos y tráfico enumerados en el punto 1 del anexo con respecto a los diferentes modos y medios de transporte.','2024-03-04','https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304','Los formatos dependen de los incisos y remisiones que requieren interpretación adicional.'),
('EU-2017-1926-SF-A04-P03-A','EU-REG-2017-1926','EU-2017-1926-ART04','Artículo 4, apartado 3, letra a)','En relación con los datos de desplazamientos y tráfico establecidos en el punto 1.1 del anexo, con excepción del punto 1.1, letra d), inciso ix), para la red RTE-T global, a más tardar el 1 de diciembre de 2019.','2024-03-04','https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304',''),
('EU-2017-1926-SF-A04-P03-B','EU-REG-2017-1926','EU-2017-1926-ART04','Artículo 4, apartado 3, letra b)','En relación con los datos de desplazamientos y tráfico establecidos en el punto 1.2 del anexo, con excepción de los puntos 1.2, letra a), incisos i) y iii), y el punto 1.2, letra c), inciso ii), para la red RTE-T global, a más tardar el 1 de diciembre de 2020.','2024-03-04','https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304',''),
('EU-2017-1926-SF-A04-P03-C','EU-REG-2017-1926','EU-2017-1926-ART04','Artículo 4, apartado 3, letra c)','En relación con los datos de desplazamientos y tráfico establecidos en el punto 1.3 del anexo, con excepción del punto 1.3, letra c), inciso iii), para la red RTE-T global, a más tardar el 1 de diciembre de 2021.','2024-03-04','https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304',''),
('EU-2017-1926-SF-A04-P03-D','EU-REG-2017-1926','EU-2017-1926-ART04','Artículo 4, apartado 3, letra d)','En relación con los datos de desplazamientos y tráfico establecidos en los puntos 1.1, 1.2 y 1.3 del anexo, con excepción del punto 1.1, letra d), inciso ix), el punto 1.2, letra a), incisos i), iii) y vii), y el punto 1.2, letra c), inciso ii), el punto 1.3, letra c), inciso iii), así como el punto 1.2, letra c), inciso i), y el punto 1.3, letra a), incisos ii) y iii), con respecto al transporte a la demanda, para las demás partes de la red de transporte de la Unión, a más tardar el 1 de diciembre de 2023.','2024-03-04','https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304',''),
('EU-2017-1926-SF-A04-P03-E','EU-REG-2017-1926','EU-2017-1926-ART04','Artículo 4, apartado 3, letra e)','En relación con los datos de desplazamientos y tráfico establecidos en el punto 1.1, letra d), inciso ix), el punto 1.2, letra a), incisos i), iii) y vii), el punto 1.2, letra c), inciso ii), el punto 1.3, letra c), inciso iii), y el punto 1.2, letra c), inciso i), y el punto 1.3, letra a), incisos ii) y iii), con respecto al transporte a la demanda del anexo, para toda la red de transporte de la Unión, a más tardar el 1 de diciembre de 2024.','2024-03-04','https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304',''),
('EU-2017-1926-SF-A04-P03-F','EU-REG-2017-1926','EU-2017-1926-ART04','Artículo 4, apartado 3, letra f)','En relación con los datos de desplazamientos y tráfico establecidos en el punto 1.4 del anexo para toda la red de transporte de la Unión, a más tardar el 1 de diciembre de 2025.','2024-03-04','https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304',''),
('EU-2017-1926-SF-A04-P04','EU-REG-2017-1926','EU-2017-1926-ART04','Artículo 4, apartado 4','Las API que proporcionen acceso a los datos estáticos, históricos y observados de desplazamientos y tráfico enumerados en el anexo a través del punto de acceso nacional establecido de conformidad con el artículo 3 serán públicamente accesibles para los usuarios de datos, cuando proceda, previamente registrados.','2024-03-04','https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304',''),
('EU-2017-1926-SF-A04-P05','EU-REG-2017-1926','EU-2017-1926-ART04','Artículo 4, apartado 5','Los usuarios de datos y los titulares de datos colaborarán para garantizar que cualquier inexactitud relacionada con los datos estáticos, históricos y observados sobre desplazamientos y tráfico se notifique sin demora al titular de datos del que proceden los datos.','2024-03-04','https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304',''),
('EU-2017-1926-SF-A05-P01','EU-REG-2017-1926','EU-2017-1926-ART05','Artículo 5, apartado 1','Los titulares de datos proporcionarán, a través del punto de acceso nacional establecido de conformidad con el artículo 3, acceso a los datos dinámicos de desplazamientos y tráfico enumerados en los puntos 2.1 y 2.2 del anexo, con respecto a los diferentes modos y medios de transporte.','2024-03-04','https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304',''),
('EU-2017-1926-SF-A05-P03-A','EU-REG-2017-1926','EU-2017-1926-ART05','Artículo 5, apartado 3, letra a)','En relación con los datos de desplazamientos y tráfico establecidos en el punto 2.1 del anexo para la red RTE-T global, a más tardar el 1 de diciembre de 2025.','2024-03-04','https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304',''),
('EU-2017-1926-SF-A05-P03-B','EU-REG-2017-1926','EU-2017-1926-ART05','Artículo 5, apartado 3, letra b)','En relación con los datos de desplazamientos y tráfico establecidos en el punto 2.2 del anexo para la red RTE-T global, a más tardar el 1 de diciembre de 2026.','2024-03-04','https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304',''),
('EU-2017-1926-SF-A05-P03-C','EU-REG-2017-1926','EU-2017-1926-ART05','Artículo 5, apartado 3, letra c)','En relación con los datos de desplazamientos y tráfico establecidos en los puntos 2.1 y 2.2 del anexo para las demás partes de la red de transporte de la Unión, a más tardar el 1 de diciembre de 2028.','2024-03-04','https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304',''),
('EU-2017-1926-SF-A05-P04','EU-REG-2017-1926','EU-2017-1926-ART05','Artículo 5, apartado 4','Cada Estado miembro podrá decidir que los titulares de datos faciliten los datos dinámicos de desplazamientos y tráfico de los diferentes modos de transporte enumerados en el punto 2.3 del anexo, en el territorio de dicho Estado miembro, a través del punto de acceso nacional establecido de conformidad con el artículo 3. En ese caso, los titulares de datos utilizarán SIRI CEN/TS 15531 y versiones posteriores o cualquier formato digital legible por máquina que pueda demostrarse que es plenamente compatible e interoperable con dichas normas y especificaciones técnicas.','2024-03-04','https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304','Condicionado a una decisión del Estado miembro; SIRI es una alternativa en este supuesto concreto.'),
('EU-2017-1926-SF-A06-P02','EU-REG-2017-1926','EU-2017-1926-ART06','Artículo 6, apartado 2','Cuando se produzcan cambios en los datos a que se refiere el apartado 1 del presente artículo, los titulares de datos actualizarán los datos estáticos, históricos, observados y dinámicos pertinentes de desplazamientos y tráfico enumerados en el anexo y los harán accesibles a través del punto de acceso nacional establecido de conformidad con el artículo 3 en un plazo que permita su utilización fiable y efectiva, de conformidad con el artículo 8. Cuando los cambios se conozcan con antelación, los titulares de datos también facilitarán dichas actualizaciones a los usuarios de datos con antelación. Además, corregirán oportunamente cualquier inexactitud que detecten o que les indiquen los usuarios de datos y los usuarios finales.','2024-03-04','https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304','El plazo es funcional y no se transforma en una fecha fija.'),
('EU-2017-1926-SF-A07-P01','EU-REG-2017-1926','EU-2017-1926-ART07','Artículo 7, apartado 1','Previa solicitud, los proveedores de servicios de información sobre desplazamientos comunicarán a otro proveedor de servicios de información sobre desplazamientos los resultados de encaminamiento sobre la base de información estática, histórica, observada y dinámica de desplazamientos y tráfico.','2024-03-04','https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304','Condicionado a solicitud.'),
('EU-2017-1926-SF-A08-P01','EU-REG-2017-1926','EU-2017-1926-ART08','Artículo 8, apartado 1','Los datos de desplazamientos y tráfico enumerados en el anexo y los metadatos correspondientes, incluida la información sobre su calidad, serán accesibles para su intercambio y reutilización dentro de la Unión de forma no discriminatoria, a través del punto de acceso nacional establecido de conformidad con el artículo 3 y en un plazo que permita la reutilización fiable y efectiva de los datos. Esos datos serán exactos, actualizados y se basarán en requisitos mínimos de calidad. A tal efecto, los Estados miembros, en cooperación con las partes interesadas pertinentes de los STI, alcanzarán un acuerdo sobre dichos requisitos mínimos de calidad de los datos.','2024-03-04','https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304','Contiene obligaciones diferenciadas para titulares de datos y Estados miembros.'),
('EU-2017-1926-SF-A08-P02','EU-REG-2017-1926','EU-2017-1926-ART08','Artículo 8, apartado 2','Los datos a que se hace referencia en el apartado 1 deberán reutilizarse de manera neutral sin discriminación o parcialidad alguna con respecto al titular de los datos. Los criterios utilizados para ordenar las opciones de desplazamiento de los diferentes modos de transporte, o combinaciones de estos, o ambas cosas, deberán ser transparentes y no estar basados en ningún factor directa o indirectamente relacionado con la identidad del usuario de datos o del usuario final o, si la hubiera, la consideración comercial relacionada con la reutilización de los datos, y deberán aplicarse de forma no discriminatoria a todos los usuarios de datos o usuarios finales participantes. La primera presentación de itinerario de viaje no deberá inducir a error al usuario final.','2024-03-04','https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304','Se preservan varias reglas relacionadas en un candidato, pendientes de revisión de atomicidad.'),
('EU-2017-1926-SF-A08-P03','EU-REG-2017-1926','EU-2017-1926-ART08','Artículo 8, apartado 3','Cuando se reutilicen los datos estáticos, históricos, observados y dinámicos de desplazamientos y tráfico, se indicará la fuente de dichos datos, si el titular de datos así lo solicita. Se indicará asimismo el intervalo de actualización de los datos estáticos, históricos, observados y, cuando sea posible, dinámicos.','2024-03-04','https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304',''),
('EU-2017-1926-SF-A09-P01','EU-REG-2017-1926','EU-2017-1926-ART09','Artículo 9, apartado 1','Los Estados miembros evaluarán si los titulares de datos y los proveedores de servicios de información sobre desplazamientos cumplen los requisitos establecidos en los artículos 3 a 8.','2024-03-04','https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304','No se trata de una regla de auditoría automática del formato.'),
('EU-2017-1926-SF-A09-P02','EU-REG-2017-1926','EU-2017-1926-ART09','Artículo 9, apartado 2','A fin de llevar a cabo la evaluación a que se refiere el apartado 1, las autoridades competentes de los Estados miembros podrán solicitar a los titulares de datos y a los proveedores de servicios de información sobre desplazamientos los siguientes documentos: a) una descripción de los datos de desplazamientos y tráfico accesibles a través del punto de acceso nacional, la información sobre su calidad y las condiciones de reutilización de esos datos; b) una descripción de los servicios de información sobre desplazamientos disponibles, incluidas, en su caso, las conexiones con otros servicios; c) una declaración acompañada de los justificantes correspondientes del cumplimiento de los requisitos establecidos en los artículos 3 a 8; d) la licencia o los acuerdos contractuales con proveedores de servicios de información sobre desplazamientos.','2024-03-04','https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304','Permiso de solicitud; no se registra como obligación del destinatario sin activación.'),
('EU-2017-1926-SF-A10-P01','EU-REG-2017-1926','EU-2017-1926-ART10','Artículo 10, apartado 1','A más tardar el 1 de diciembre de 2019, los Estados miembros remitirán a la Comisión un informe sobre las posibles medidas emprendidas para establecer un punto de acceso nacional y sobre las modalidades de su funcionamiento.','2024-03-04','https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304','Fecha literal y ámbito explícito. Obligación histórica, vencida.'),
('EU-2017-1926-SF-A10-P02','EU-REG-2017-1926','EU-2017-1926-ART10','Artículo 10, apartado 2','Los Estados miembros proporcionarán a la Comisión la siguiente información dentro de los informes sobre los progresos realizados a que se refiere el artículo 17, apartado 3, de la Directiva 2010/40/UE: a) los avances realizados en términos de accesibilidad e intercambio de los tipos de datos de desplazamientos y tráfico establecidos en el anexo; b) la cobertura geográfica de los datos que figuran en el anexo accesibles a través del punto de acceso nacional establecido de conformidad con el artículo 3, y su calidad, incluidos los criterios utilizados para definir esa calidad y los medios utilizados para supervisarla; c) la conexión de servicios de información sobre desplazamientos; d) los resultados de la evaluación del cumplimiento a que se refiere el artículo 9, apartado 1; y e) cuando proceda, una descripción de los cambios en el punto de acceso nacional establecido de conformidad con el artículo 3.','2024-03-04','https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304','La periodicidad y el contexto del informe remiten a otra norma; NEEDS_REVIEW.'),
('EU-2017-1926-SF-A04-P01-ROAD','EU-REG-2017-1926','EU-2017-1926-ART04','Artículo 4, apartado 1, letra a)','Por lo que se refiere al transporte por carretera, mediante el formato normalizado a que se refiere el artículo 4 del Reglamento Delegado (UE) 2015/962.','2024-03-04','https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304','Remisión a otro acto; se conserva sin interpretarlo.'),
('EU-2017-1926-SF-A04-P01-OTHER','EU-REG-2017-1926','EU-2017-1926-ART04','Artículo 4, apartado 1, letra b)','Por lo que se refiere a otros modos de transporte, mediante una de las siguientes normas y especificaciones técnicas, o mediante cualquier formato digital legible por máquina que pueda demostrarse que es plenamente compatible e interoperable con dichas normas y especificaciones técnicas, por ejemplo, a través de convertidores y validadores automáticos: i) NeTEx CEN/TS 16614 y versiones posteriores; ii) las especificaciones técnicas establecidas en el Reglamento (UE) n.o 454/2011; iii) los documentos técnicos publicados bajo la autoridad de la Conferencia de servicios de pasajeros de la IATA; iv) Transmodel EN 12896, cuando no exista un protocolo de intercambio de referencia.','2024-03-04','https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304','La fuente ofrece alternativas; no implica NeTEx universal.'),
('EU-2017-1926-SF-A04-P01-SPATIAL','EU-REG-2017-1926','EU-2017-1926-ART04','Artículo 4, apartado 1, letra c)','En relación con la red espacial, los requisitos establecidos en el artículo 7 de la Directiva 2007/2/CE.','2024-03-04','https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304','Remisión a otro acto; se conserva sin interpretarlo.'),
('EU-2017-1926-SF-A04-P02','EU-REG-2017-1926','EU-2017-1926-ART04','Artículo 4, apartado 2','Los datos estáticos, históricos y observados sobre desplazamientos y tráfico enumerados en el punto 1 del anexo, a los que son aplicables NeTEx y DATEX II, se representarán mediante perfiles mínimos de la UE o nacionales.','2024-03-04','https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304','Aplicabilidad de los estándares condiciona el alcance.'),
('EU-2017-1926-SF-A05-P01-ROAD','EU-REG-2017-1926','EU-2017-1926-ART05','Artículo 5, apartado 1, letra a)','Por lo que se refiere al transporte por carretera, mediante los formatos indicados en los artículos 5 y 6 del Reglamento Delegado (UE) 2015/962.','2024-03-04','https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304','Remisión a otro acto; se conserva sin interpretarlo.'),
('EU-2017-1926-SF-A05-P01-OTHER','EU-REG-2017-1926','EU-2017-1926-ART05','Artículo 5, apartado 1, letra b)','Por lo que se refiere a los demás modos de transporte, mediante cualquiera de las siguientes normas y especificaciones técnicas, o mediante cualquier formato digital legible por máquina que pueda demostrarse que es plenamente compatible e interoperable con dichas normas y especificaciones técnicas, por ejemplo, a través de convertidores y validadores automáticos: i) SIRI CEN/TS 15531 y versiones posteriores; ii) las especificaciones técnicas establecidas en el Reglamento (UE) n.o 454/2011.','2024-03-04','https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304','La fuente ofrece alternativas; no implica SIRI universal.'),
('EU-2017-1926-SF-A05-P02','EU-REG-2017-1926','EU-2017-1926-ART05','Artículo 5, apartado 2','Los datos dinámicos sobre desplazamientos y tráfico a que se refieren los puntos 2.1 y 2.2 del anexo, a los que son aplicables SIRI y DATEX II, se representarán mediante perfiles mínimos de la UE o nacionales.','2024-03-04','https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304','Aplicabilidad de los estándares condiciona el alcance.'),
('EU-2017-1926-SF-A04-P06','EU-REG-2017-1926','EU-2017-1926-ART04','Artículo 4, apartado 6','Los datos facilitados por los titulares de datos a través del punto de acceso nacional no incluirán datos personales, tal como se definen en el artículo 4, apartado 1, del Reglamento (UE) 2016/679.','2024-03-04','https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304','La definición de datos personales remite a un acto externo.')
INSERT INTO compliance.requirement_candidates
(candidate_id,requirement_id,source_document_id,source_provision_id,source_fact_id,legal_classification,requirement_class,requirement_type,description,responsible_party,beneficiary_party,is_mandatory,is_conditional,accessibility_requirement,deadline_date,review_status,review_notes)
VALUES
('EU-2017-1926-CAND-A03-P01-001','EU-2017-1926-REQ-A03-P01-001','EU-REG-2017-1926','EU-2017-1926-ART03','EU-2017-1926-SF-A03-P01-ESTABLISH','OBLIGATION','ACCESS','ESTABLISH_NAP','Cada Estado miembro debe establecer un punto de acceso nacional.','Estado miembro','Usuarios de datos',TRUE,FALSE,'Establecer el punto de acceso nacional previsto en el artículo 3.',NULL,'APPROVED','Aprobación propuesta por soporte textual directo; sujeto a revisión humana del diseño.'),
('EU-2017-1926-CAND-A03-P01-002','EU-2017-1926-REQ-A03-P01-002','EU-REG-2017-1926','EU-2017-1926-ART03','EU-2017-1926-SF-A03-P01-SINGLE','OBLIGATION','ACCESS','SINGLE_ACCESS_POINT','El punto de acceso nacional debe servir como punto único de acceso a las categorías de datos y actualizaciones enumeradas para el territorio del Estado miembro.','Estado miembro','Usuarios de datos',TRUE,FALSE,'Punto único para las categorías y titulares cubiertos por el artículo 3, apartado 1.',NULL,'APPROVED','La descripción conserva el alcance territorial y material indicado en la fuente.'),
('EU-2017-1926-CAND-A03-P03-001',NULL,'EU-REG-2017-1926','EU-2017-1926-ART03','EU-2017-1926-SF-A03-P03','OBLIGATION','DISCOVERY','NAP_LOCATION_SERVICE','El punto de acceso nacional debe prestar servicios de localización a los usuarios de datos.','Punto de acceso nacional','Usuarios de datos',TRUE,FALSE,NULL,NULL,'NEEDS_REVIEW','Revisar qué significa operativamente "servicios de localización"; no inferir tecnología.'),
